from pathlib import Path
from collections import Counter
import json,re

O=Path(__file__).resolve().parents[1]
B={b['id']:b for b in json.loads((O/'_source/blocks.json').read_text())}
edits=[]
def edit(i,title,problem,reason,benefit,text):
    bid=f'B{i:04d}';b=B[bid]
    assert 329<i<526 and b['kind']=='p' and not b['style_name'].startswith('heading')
    assert text!=b['text']
    assert re.findall(r'\[\d+\]',text)==re.findall(r'\[\d+\]',b['text']),(bid,'citations')
    nums=lambda t:Counter(re.findall(r'\d+(?:\.\d+)?',t))
    assert nums(text)==nums(b['text']),(bid,'numbers',nums(text)-nums(b['text']),nums(b['text'])-nums(text))
    heads=[x for x in B.values() if 329<=x['index']<=i and x['style_name'].startswith('heading')]
    edits.append({'block_id':bid,'title':title,'section':heads[-1]['text'],'old_text':b['text'],'new_text':text,'problem':problem,'reason':reason,'benefit':benefit})

edit(330,'章首：从共同定义进入本章问题','原文在提出问题后即转为目录式预告，研究问题与实验检验之间的联系较弱。','保留与第二章的承接，用“确定哪些监督继续使用”串联构造、学习和比较。','读者先把握本章要回答的问题，再理解方法介绍与实验分析的分工。','第二章统一了完整对象表示与评价条件。本章据此研究训练文本局部改写后，哪些组件与关系监督仍可用于学习。方法部分说明增强视图如何构造、可靠因素如何进入学习目标，以及相应算法的性质；实验部分通过受控比较，分别检验整体训练配置、成对目标及其审核成本。')
edit(332,'引言：将局部改写风险落到具体关系变化','“获得新的解释”较抽象，末句对样本增加与错误监督的联系还可更直接。','以组件角色和关系判断为主线，保留语义相近仍可能影响标签的几个具体情形。','改写为何需要审核更明确，不把文本相似误读为监督不变。','在端到端论辩挖掘中，组件文字既表达自身的论辩角色，也为组件间关系提供依据。局部改写即使保持句意相近，仍可能改变支持方向、削弱跨边界理由，或改变原本未标注关系的组件组合所具有的含义。若直接将全部旧标签复制到增强文本，新增样本就可能带入错误监督。')
edit(333,'方法引入：按构造、审核和比较展开','“可追踪的增强视图”与后续操作之间的关系需要进一步落地，步骤目的可更清楚。','依次说明位置迁移、状态审核和固定条件下的目标比较，保留所有掩码规则。','读者可沿操作顺序理解如何把原始标注转为可用的增强监督。','本章在组件位置变化、关系语义可能改变的条件下，构造可追踪的增强视图，并将通过检查的监督用于训练。具体而言，先定义改写的关系影响域，在字符坐标上迁移全部组件；再分别审核组件与关系，将状态改变、待定及未审核因素的掩码置零；最后固定视图和掩码，比较无成对、组件成对与完整成对学习。')
edit(334,'基本术语：区分视图、因素与成对学习','三个概念集中于分号连接的长句，读者需要同时记住对象与操作。','分别定义视图和因素，再解释成对学习比较什么、约束什么。','后文的掩码、辅助头和对齐目标有清楚的术语基础。','同一篇原文及其改写版本称为不同“视图”。“因素”是可单独决定是否参与监督的一项判断，包括组件类型判断，或一组完整端点之间的关系状态判断。成对学习比较原文与改写中对应因素的模型输出，使通过检查的对应因素在两种表达下具有一致的预测分布。')
edit(338,'总体框架：明确两个阶段的输入与输出','构造输出、学习信号、图示与贡献归属连续出现，阶段接口容易被技术名词遮蔽。','以增强构造和参数学习为两条主线，再说明继承部分与本章新增部分。','读者能直接判断构造阶段向训练阶段传递哪些信息。','整体框架分为增强构造与参数学习。构造阶段以训练文档和原生标注为输入，输出增强全文、全部组件的对应φ及可靠因素掩码。学习阶段保留原文的完整生成监督，增强侧仅使用通过检查的因素。图3-2展示两个视图进入共享生成器后的监督路径。类型条件LoRA、线索提示和句子监督沿用已有配置，本章新增关系影响域约束、可靠监督接口及受控的成对学习目标。')
edit(339,'因素掩码：解释标记控制的对象','原文定义准确，但“它”与多个监督用途连续衔接，读者可能将掩码理解为输入遮蔽。','先说明0/1标记的作用，再直接点明它控制监督参与，不改变输入或原始标注。','明确掩码作用于学习信号，便于理解后文保留全文但屏蔽部分标签的流程。','因素掩码是与监督一同保存的0/1标记：1表示参与相应的增强侧监督或对齐，0表示不参与。掩码不遮蔽输入文字，也不删除原始金标；组件与关系的掩码分别保存。')
edit(344,'类型门控：按可见字段说明开启与关闭','字段顺序、门控触发、语料类型和教师强制限制集中陈述，可进一步突出时间顺序。','按字段输出进程解释门控，再列出不触发区域与禁止使用后续答案的条件。','读者能判断当前解码位置是否允许使用结论分支，避免把金标前缀误作未来信息。','全局分支参与所有位置的计算，结论分支由 gt∈{0,1} 控制。输出字段依次为id（组件编号）、type（类型）和span（原文跨度）。当可见前缀已完整输出结论类型字段时，门控从该组件的后续字段开启，到组件结束时关闭。AAEC和CDCP分别以Claim/MajorClaim和Policy/Value触发；输入、未闭合类型字段及关系区域均令 gt=0。教师强制训练仅使用当前位置之前的输出前缀，不读取后续答案来决定门控。')
edit(348,'线索提示：说明触发规则与标签的区别','多个分号连接不同性质的信息，继承规则与效果边界的主次关系不够突出。','先讲词典的操作范围，再讲两个视图如何触发，最后说明收益与继承归属。','提示启用、结论标签和新增贡献不会被混为一谈。','词典仅决定是否启用提示，不赋予结论标签；原文与增强文分别依据各自文本触发。话语标记的收益不能由标记数量直接推定[40]。该规则沿用MCR-BR配置，不单独计为本章新增机制。')
edit(356,'改写范围：将文字替换与结构定义分开','一段内同时界定增强任务与内部/跨边界关系，两个层次的承接可更自然。','先限定改写操作，再从组件集合引出内部和跨边界的定义依据。','读者不会将改写集合等同于连续段落，也不会将增强理解为重新标注结构。','本章通过替换已标注组件的文字进行训练数据增强，不重写整篇文章，也不重新决定组件类型或关系答案。改写集合由组件组成，可以分布在不同段落中。因此，“内部”与“跨边界”依据组件是否属于该集合定义，并不直接等同于句内、跨句或跨段。')
edit(357,'槽位与正关系：把容易混淆的术语解释具体','“只读”容易被理解为位置不变，“正关系”也容易被理解为只有支持关系。','将每个术语的操作含义和容易误读的边界相邻陈述。','读者可同时区分文字是否改写、位置是否移动和关系是否有显式标签。','“槽位”是已定位到原文字符区间、允许替换文字的组件片段；“只读端点”是文字保持不变的其他组件。只读端点的坐标仍须更新，因为前文改写可能改变文本长度。下文“正关系”指带有明确原生关系标签的关系，与无边状态NONE相对；attacks同样属于正关系，并不限于支持关系。')
edit(360,'动机例子：区分解释用集合与默认改写集合','关系示例与自动选择规则较密集，读者可能把局部观察集合当作默认结果。','先按同一例子分类关系，再明确观察集合仅用于解释，默认集合仍遵守完整入源规则。','例子更直观，同时保留示意选择与实际默认选择之间的区别。','表中T4、T5、T6分别以supports指向T3，T4→T7没有标注边。取局部观察集合A={T3,T4}时，T4→T3是内部正因素，T5→T3和T6→T3是跨边界正因素，T4→T7是跨边界NONE。该集合仅用于说明分类，不是默认自动选择的结果。默认以T3为中心时，所有指向T3的完整源成员T4、T5、T6均进入改写集合。')
edit(363,'两条接受路径：分开位置分类与审核状态','空间位置、语义状态与接受策略并列出现，概念切换较快。','先区分两个分类维度，再说明默认掩码和完整筛选各自如何处理失败因素。','读者能够根据图中分支判断关系审核失败是否导致整例拒绝。','“内部／跨边界”说明端点相对改写集合的位置，“正关系／NONE／语义未知”说明因素状态，两类信息分别记录。默认路径保留有效组件，屏蔽不确定的关系监督；完整筛选路径则在任一可审核因素失败时拒绝整例。已知联合源真子集的语义未知状态按3.3.3节处理，不视为已确认的NONE。')
edit(365,'改写集合：按回退、组建和例外规则展开','中心回退、源成员收集、元数限制及只读规则在长段中密集排列。','依照实际选择顺序解释，并把金标关系保留规则放在元数限制旁边。','能够直接区分中心选择、改写集合与新增NONE预算，减少对金标被截断的误解。','优先集合为空时，按同一顺序从全部合法金标组件中回退选择，并记录fallback；组件集合为空时保留原文，跳过增强。改写集合A包含中心及所有指向中心的金标关系的完整源成员，去重后不再递归扩展。没有入关系时只改写中心；金标超边即使超过三个源成员也完整纳入，不受新增NONE因素元数预算的截断。其余组件的文字保持只读。')
edit(366,'异常与预算：将跳过条件和覆盖记录对应','异常处理、两种审核模式、运行上限和中心选择边界混在一段中，读者容易漏掉条件归属。','逐项写明什么情况跳过、两种模式报告什么，再给出共同预算。','具体失败出口和覆盖条件更容易查阅，保留结论中心优势尚需检验的边界。','槽位重叠或完整输入超过冻结的上下文上限时，跳过该文档的增强并记录原因，不删除源成员，也不改选中心。默认因素掩码版本只审核声明的有限子集；完整筛选版本在无法处理完整影响域时跳过，两种版本分别登记审核覆盖。不同模型的上下文及调用上限由运行清单给出，缺失时不启动生成。每篇文档最多尝试四次、接受两个变体，原始样本始终保留。这些规则限定改写范围和资源预算，不预设结论类中心优于其他中心。')
edit(367,'因素宇宙：让标签定义与未知例外相邻','因素定义、AAEC枚举、NONE、语义未知和并存标签连续出现，定义层次较密集。','按对象、标签、未知例外和并存状态组织，保留各项协议条件。','读者能够分清进入候选的端点组合与能够参与语义监督的因素。','记 ΩC 为协议允许的完整端点组合集合，因素 ω=S,v 由非空源组件集合 S 和目标 v 构成。AAEC中 S=1，枚举全部合法有向组件对，内部正边、边界正边及其余合法对均纳入候选。因素标签 yω 表示协议规定的关系状态。在可审核的有限端点组合集合内，无标注关系记为NONE；已标注联合源真子集的语义未知例外按3.3.3节处理，先从语义监督和审核域中排除。同一端点组合若允许多个标签，则以合法标签组合表示状态，保留全部监督。')
edit(370,'NONE范围：说明元数预算的具体局限','“有限宇宙”和“监督偏置”之间的联系可更直接，局限的作用对象需要明确。','先限定NONE的定义范围，再解释长超边缺少什么对照及需要怎样诊断。','读者能够理解三源预算带来的具体限制，不将辅助头用于超出其范围的正确率判断。','NONE仅在上述有限宇宙中定义，不覆盖组件集合的全部子集。由于新增候选最多包含三个源成员，更长的金标超边缺少同元数的NONE对照，可能引入与长度相关的监督偏置，需按源元数（源成员个数）诊断。该辅助头不用于估计长超边的完整对象正确率。')
edit(373,'影响域边界：明确完整性相对于什么成立','内部/边界、NONE解释、域外漂移与资源裁剪连续切换，易把“完整”理解为所有语义影响。','先解释集合与端点位置，再说明因素宇宙范围和域外检查的分工。','保留形式定义与自然语言语境影响的区别，明确近似设置需要报告什么。','其中 ΩsemC=ΩC∖Usem，未知集合见3.3.3节，AAEC没有这一联合源子集例外。二元情形为 {u,v:u∈A∨v∈A,u,v∈ΩsemC}。全部端点位于 A 中的是内部因素，只有部分端点位于 A 中的是边界因素。“完整”仅相对于预先声明的因素宇宙成立；NONE表示标注协议中的无边状态，不表示任意语义解释下都没有联系。改写仍可能通过指代或篇章语境影响两个只读端点，这类域外漂移另作人工审计。资源裁剪版本须单独报告因素覆盖率，并标记为近似设置。')

# Remaining edits are appended below before export.
edit(375,'生成配置：先交代共用模型，再明确输出约束','输入、采样参数和输出约束连续堆叠，模型共用的比较条件不够醒目。','先说明四种跨骨干配置共用增强视图，再分开陈述输入、解码设置与输出形式。','读者可直接识别增强来源、冻结参数以及模型允许修改的对象。','增强生成器A固定为未加载任务LoRA的Qwen3.5-9B，跨骨干实验的四种配置共用该模型生成的增强视图。其输入包括训练全文、可改写槽位及类型、只读端点目录和影响域标签。任务设置固定为temperature=0.7、top-p=0.9，通过chat_template_kwargs中的enable_thinking=false关闭thinking，输出上限为2048 token。模型仅返回组件ID到替换文本的JSON映射，不新增组件，也不修改类型或关系表。')
edit(378,'组件身份：依次解释版本、坐标更新和双射边界','身份定义、显示ID、坐标派生及拒绝条件密集排列，“双射”作用对象容易被忽略。','按身份定义、回填操作、映射性质和失败出口组织，保留对只读组件的坐标更新。','读者能区分追踪编号、规范身份和位置变化，理解坐标输运为何需要覆盖全部组件。','组件的规范身份由文档版本、原文字符半开区间和原生类型确定。增强全文属于新的文本版本，记为d′；显示ID只追踪组件对应，不能替代坐标或版本身份。回填后先更新全部组件的字符区间，再派生评价token与模型子词表示，只读组件的位置也随前文长度变化而更新。因此，φ是组件之间的双射，而非字符或token位置之间的双射。关系及超边的全部端点均按同一φ迁移。若槽位重叠、坐标往返不一致或端点无法无损输运，则拒绝该视图并保留原始样本。')
edit(381,'组件审核：分开结构检查、模型配置与拒绝规则','检查对象和审核器参数交错，末句的拒绝条件缺少清楚的执行层次。','先说明所有版本共用的结构检查，再介绍审核模型及逐项核查内容。','格式有效与组件语义保持成为可辨认的两层检查，模型条件也更便于复核。','所有版本均先检查JSON、槽位身份、坐标往返和完整端点引用，再核查组件含义、角色、指代、否定与模态。审核器V固定为Qwen3.5-9B官方权重，使用独立上下文，不加载抽取LoRA；关闭thinking，采用贪心解码，每次最多输出1024 token。跨骨干实验共用同一审核结果。格式失效、含义改变或意义待定时，拒绝该变体，并保留原文和金标。')
edit(382,'有限审核：说明覆盖范围与资源不足时的处理','抽样规则、语义未知排除和资源不足分支挤在一起，关系学习与组件学习的处理差异不易辨认。','先交代审核集合，再说明未知项与资源上限各自如何影响监督。','读者能看清“未审核”保留为未确认状态，资源不足也不会自动抹去有效组件监督。','通过组件检查后，默认采用因素掩码。关系审核子集 JA⊆DA 纳入全部受影响正关系，并按固定哈希从内部NONE和跨边界NONE中各抽取至多4项。CDCP联合源中已定义为语义未知的真子集不作为NONE负例。若资源不足以核查全部正关系，本次变体不进入关系学习，但通过检查的组件仍可用于组件级监督。未审核的NONE保留为未确认状态。')
edit(383,'掩码条件：让关系通过与端点通过相互对应','关系掩码、组件掩码及可靠性的含义分布在长句中，容易漏读端点必须通过的条件。','逐一说明关系状态条件、组件核查条件和端点约束，最后界定可靠性的含义。','关系掩码取值的必要条件更完整可查，避免把模型审核通过理解为人工语义保证。','审核器分别判断原文与改写视图中的因素状态。只有原标注获认可、改写后状态一致且完整端点对应有效时，才令 mRω=1；原标签分歧、状态变化或待定时均置为0。组件另行保存 mCc。参与头监督和对齐的只读端点也须在全文上下文中审核，字面未变不足以确认其论辩角色稳定。关系掩码为1还要求全部端点的组件掩码为1。上述判断由固定模型给出，因而“可靠”表示通过预先声明的检查，并非人工金标准层面的语义保证。')
edit(384,'三类状态：将审核状态与语义定义分开','待定、未审核和语义未知使用相近表述，容易被理解为同一种关系标签。','以是否执行判断、是否确认保持分别解释待定与未审核，再单独引出语义未知。','掩码值、关系标签与语义未知各自表示什么更加明确。','“待定”表示已执行审核，但尚不能确认原有状态是否保持；“未审核”表示未执行该项判断。两者均不能提供已确认的增强监督，掩码取0；掩码为0不等于将关系标签改为NONE。“语义未知”则指无法从联合源标注推出其真子集的单独语义标签，与上述审核状态分开定义。')
edit(385,'策略对照：明确保留什么与参与什么','默认策略的接纳、追踪图的保存以及完整筛选的拒绝规则连续切换。','先说明默认策略如何保留组件和输运图，再交代损失入口及完整筛选的整例拒绝规则。','读者能区分“数据仍保存”与“标签参与训练”，并理解两种策略的比较对象。','默认策略保留通过检查的组件，不因某个关系未通过审核而舍弃全部有效组件，也不将该关系改为NONE。变体仍保存完整输运图以便追踪，增强侧损失只使用掩码为1的标签。完整筛选对照检查声明影响域内的全部因素，任一因素变化或待定即拒绝整例。其余生成和训练资源按共同规则登记，分别比较两种策略的监督覆盖、训练效果与成本。')
edit(387,'审核执行：把独立上下文与误差独立区分','独立上下文、隐藏标签和独立质量审计连续出现，读者可能将程序隔离理解为误差独立。','按模型输出、程序比较和质量审计三个步骤说明，并保留同家族误差相关的限定。','自动审核与人工质量审计的身份更清楚，避免从上下文隔离推出统计独立。','审核器V在分开的上下文中处理原文和变体，并隐藏待核查标签。它先输出原生组件类型或关系状态，再由程序与原标签比较；若未返回合法标签或置信判断待定，掩码取0。第3.6.3节中的A、B、C是独立质量审计的角色标识，与自动审核器V区分。同一家族模型即使使用不同模块和上下文，其判断误差仍可能相关。')
edit(388,'联合源示例：说明不匹配为何不能推出无关系','对象匹配和语义关系的转折较急，例子中的判断对象可更明确。','先陈述严格评价的匹配要求，再解释缺少源成员的预测与语义否定之间没有推出关系。','完整超边评价与语义NONE的区别通过同一例子得到解释。','严格抽取评价要求完整预测对象与金标对象匹配。例如，金标为 h={c1,c2},c3,Reason 时，预测 {c1},c3,Reason 因源集合不同而不能匹配该金标。然而，完整联合理由成立，并不能推出其中单一成员在语义上既不支持也不反对目标。')
edit(389,'未知集合：按判定规则、优先级和使用范围解释','未知定义、正标注优先及完整筛选范围并列，规则之间的依赖关系不够显式。','先定义真子集进入未知集合的条件，再说明显式标注优先和审核域排除规则。','读者可以依条件判断一个因素是否被屏蔽，同时理解完整筛选没有把未知项算作通过。','据此，训练语义头定义未知集合 Usem：对已标注联合源，若指向同一目标的非空真子集没有任何单独正关系标注，则将该端点因素列为语义未知。显式正标注优先，已有单源正关系不被屏蔽。可审核因素宇宙为 Ωsem=Ω∖Usem，完整影响域与抽样集合均在其中定义。因此，完整筛选的“全部”仅指已声明的可审核域；未知项另行计数，不计为审核通过。')
edit(390,'标签用途：分清语义监督、对象评分与推理选择','三个阶段对负例和NONE的用法压在一个长段里，0标签的含义容易混用。','沿训练语义头、原文生成、第四章评分和推理决策依次说明标签作用。','相同真子集在不同任务中的标签理由更易理解，避免误删金标或误赋语义NONE。','原文与变体的语义关系头均不将 Usem 作为NONE负例，其监督和对齐掩码均为0；原文完整生成目标仍保留原始超边，金标不删不改。第四章评分器判断完整对象是否与标注精确匹配，因此可将该真子集作为对象不匹配的负例，但其0标签不表示语义上没有关系。推理中的NONE仍表示该槽位未选正关系。标注存在性、语义审核和推理决策由此分别处理。')
edit(393,'集合层级：按定义、实际审核和损失入口递进','三个集合的名称连续排列，但进入训练需要经过的层次可更鲜明。','将各集合承担的功能与默认/完整策略逐一对应。','读者能将图示分支、公式包含关系和实际损失计算联系起来。','完整影响域DA规定定义范围，JA记录实际审核范围，通过审核的RA才进入增强关系损失。默认JA通常小于DA；完整筛选令JA=DA，但语义未知Usem始终排除在两者之外。图3-1的两个分支对应这一集合层级。')
edit(395,'回放案例：先说明操作，再界定验证目的','真实文档身份、空格处理和验证目的集中呈现，读者可能将确定性处理与自然改写混读。','按语料、槽位选择、实际处理和验证用途展开，保留文件记录位置。','案例可复现的操作更清楚，其能够验证的接口范围也更明确。','本节选用AAEC训练文档essay001及其原生标注，以T3为中心，按完整入源规则得到A={T3,T4,T5,T6}。对四个槽位分别将首次ASCII空格替换为两个空格，其余字符逐字保留。该确定性处理已执行，用于验证输运和掩码接口。原文内容见表3-1，全文及全部迁移对象保存在augmentation_example_v9.json。')
edit(398,'迁移结果：把位移原因与核查顺序连接起来','坐标含义、整体后移及脚本检查之间的关系可以更连贯。','先从新增字符解释位移，再交代组件切片检查与关系端点输运。','表中的数字变化有直接原因，组件和关系的验证顺序也更清楚。','表中坐标均为字符半开区间。四个改写槽位各增加一个空格，因此末段只读组件的起止位置整体后移4个字符，显示ID与原生类型保持不变。程序逐一检查11个组件在新全文中的切片，确认规范化空白后与原片段一致，再按同一φ输运每条原生关系的全部端点。')
edit(402,'拒绝案例：将触发条件与验证边界相邻说明','处理操作、拒绝结果和准确率边界虽齐全，但拒绝依据在叙述中不够突出。','以T3内容一致性失败为中心，依次说明替换来源、程序判定和保留结果。','读者能明确此次拒绝由什么触发，也不会将它理解为语义审核器的准确率证据。','第二次处理将同文档T7的真实原文“competition makes the society more effective”回填到T3槽位。由于规范化空白后的内容与T3不再一致，程序的保守等价检查拒绝该视图；接受视图数仍为1，原文及第一条视图均保留。替换文本直接来自原语料，该例用于检验组件内容保持的检查流程，不用于估计语义审核器V对自然改写的准确率。')
edit(403,'案例收束：把接口核对与总体质量评价分开','脚本核对和主实验审计衔接紧密，容易混淆两类验证所回答的问题。','先汇总本例已核对对象，再指明自然改写记录和独立质量审计的归属。','坐标、覆盖和语义可靠性各自的证据来源更清楚。','脚本已核对本例的11个坐标往返、110项因素身份、68项影响域归属及两条处理结果。主实验的自然改写与自动语义判断由A/V模块记录，独立质量审计按第3.6.3节的分层设计汇总。坐标正确性、审核覆盖和语义可靠性据此分别评价。')
edit(405,'成对目标动机：用同一例子串联审核、对齐与标签锚定','段落同时承担例子、目标定义和退化风险解释，若不突出依赖关系，读者容易只记住分布相似。','从组件通过不代表关系通过出发，说明成对比较的对象，再引出金标锚定的必要性。','成对学习为什么需要审核与标签监督更加明确，保留不要求文字形式一致的条件。','增强视图通过检查后，训练进一步利用不同表达之间可靠的论辩功能对应。以表3-1为例，T4改写后若通过组件检查，其Premise标签即可参与增强侧监督；T4→T3的supports与T4→T7的NONE仍须分别通过关系检查，不能由组件检查结果推定。成对目标比较这些可靠因素的类别分布，不要求新旧文本的词序、长度或坐标相同。由于两个视图可能共同预测错误，分布对齐还须结合金标锚定，即使用已知原生标签监督预测。')
edit(411,'输入隔离：明确辅助头与抽取生成器分别看到什么','“输入表示”“金标跨度”和“生成器输入”相邻出现，金标是否进入模型输入需要反复辨别。','先定义辅助分类器，再明确抽取生成器的文本输入及构造阶段标注的使用边界。','训练时定位监督对象与向生成器提供答案信息得以区分。','组件类型头和关系状态头均为辅助分类器，读取共享生成器的输入隐藏表示，并以金标跨度定位训练因素。抽取生成器的输入仅包括任务指令及原文或增强文。金标槽位、类型与关系条件只用于构造训练视图和监督，不作为抽取生成器的输入。')
edit(414,'全文表示：说明补充上下文不改变因果结构','“通道”较抽象，补充什么信息、没有改变什么结构可以直接说明。','以早期子词表示的上下文限制引出拼接操作，并保留金标类型不输入的条件。','读者能理解该设计的作用，同时避免误解为修改注意力机制。','因果模型中，早期 token 只能访问左侧上下文。拼接 endxh 可为组件跨度表示补充全文上下文，但不改变因果注意力结构。组件头也不接收待预测的金标类型。')
edit(418,'关系特征：将特征构成、坐标用途和监督对象分层说明','长段连续罗列位置统计、归一化、对象身份限制和评价阶段处理，主次关系较密集。','先定义分类器和特征，再说明坐标用途，最后交代关系监督对象与辅助头的使用阶段。','读者更易复现特征输入，也不会把评价token特征当成规范对象身份。','其中，fC、fR为两层感知机，Pool对源成员表示取算术均值。η包括源成员数、源起点的最小值与均值、源终点的最大值与均值，以及目标起止位置。位置由规范字符区间派生为评价token坐标，并除以文档token数。这些坐标仅作输入特征，不参与规范对象去重，也不替代字符残差；η不含待预测的关系标签。二元关系使用单一源表示，超边以完整源集合及目标为监督对象，状态包含NONE。两个辅助头均在开发评价和测试时移除。')
edit(426,'空集合分支：分开归一化目的与无可靠因素时的处理','两级平均的目的和空集合的处理紧邻，可进一步突出各自对应的情形。','先解释防止NONE数量主导，再分别说明关系和组件集合为空时的取值。','公式的归一化逻辑和边界情况更容易与实现对应。','两级平均可避免NONE因素因数量较多而主导关系对齐损失。可靠关系集合为空时，关系对齐项置零，不人为添加关系，原文全部关系的生成监督仍保留。A+ 为空时，组件对齐项同样置零。')
edit(431,'增强侧监督：将全文输入与完整生成答案分清','原文和增强文的职责用分号连接，“含未审核关系”对生成监督的限制可更明确。','分别说明原文保留哪些目标、增强文为什么仅提供输入视图。','读者能理解保存完整输运图不等于用它作为全部标签均可靠的答案。','设源文档 d 接受 md 个视图。原文承担完整图生成与继承的句子监督；增强文仅提供输入视图，其含有未审核关系的输运图不作为完整生成答案。头监督定义为')
edit(435,'归一化边界：按无视图、无关系和批次权重展开','默认系数、空关系分支、组件非空保证和批次归一化集中在一段中，条件顺序可更清楚。','依训练数据可用程度说明各项是否计算，再交代源文档权重。','读者可以依条件判断损失项，理解变体较多为何不会自动增加文档权重。','默认 λsup=1、λC=λR=0.5。没有变体时仅保留原文对应项；有变体但无可靠关系时，关系对齐置零，组件学习仍可进行。接受视图中的被改写组件均已通过检查，mC 均为1，因此计入 md 的视图不会产生空组件项。批内按源文档平均，梯度累积末批按实际文档数归一化，使接受变体较多的源文档不会自动获得更高权重。')
edit(436,'权重解释：说清固定总权重带来的原文占比变化','归一化的好处、代价和消融可比性连续出现，需要明确哪些比较受影响。','先说明总权重与原文占比的关系，再分别讨论数据策略比较和固定视图消融。','读者能识别完整筛选比较中包含的数据策略差异，也能理解成对目标消融为何不受其影响。','按 1+md 平均可固定每篇源文档的头监督总权重，但原文在其中的占比随接受视图数变为 1/1+md；原文完整生成损失 LICIC 保持不变。完整筛选与因素掩码通常接受不同数量的视图，因此两者的比较也包含原文占比差异，这是数据策略的一部分。成对学习消融则固定视图与掩码，不受该差异影响。')
edit(437,'梯度路径：分别交代更新对象与推理用途','多个模块的更新、冻结、移除和评分用途密集排列，训练接口与推理接口容易混读。','先沿损失来源说明参数更新，再说明基础权重、辅助头和独立评分器的关系。','读者能清楚追踪哪些参数由哪些目标更新，避免把辅助头概率当成完整对象正确率。','两个视图均保留梯度。生成与句子损失更新继承模块，组件头、关系头及成对项通过输入表示更新全局LoRA；由类型前缀门控的结论专项分支只随相应生成路径更新。基础权重保持冻结，辅助头在评价时移除。推理评分器另行训练，这些辅助头的类别概率不作为完整对象正确率。')
edit(438,'额外版本：将启用条件与默认设计的理由连接起来','额外版本和默认排除理由可更直接对应，避免读者以为默认遗漏了生成目标。','先说明何时允许增加增强图生成损失，再解释默认不采用的具体原因。','增强侧目标的选择有明确条件与理由，保留独立命名和控制更新量的要求。','若全文改写后的全部标签均获确认，可另设计算增强图生成损失的版本，并独立命名、控制更新量。默认设计不采用该版本，以避免未审核标签经生成目标重新进入训练。')
edit(440,'算法导语：让阶段划分与数据使用范围对应','两阶段介绍之后接数据划分边界，过渡略显机械。','用构造产物和训练方式串联两个阶段，再统一交代训练、开发和测试的分工。','算法的输入输出逻辑更清楚，数据使用范围保持明确。','算法3-1分为增强构造和参数学习两个阶段：先在固定预算内生成并筛选文本变体，再按源文档归一化训练。数据构造与损失计算均只访问训练划分；开发集用于按第二章2.5节选择参数并执行停止规则，测试标签不参与这些过程。')
edit(485,'算法补充：按预算、更新路径和异常批次说明','参考预算、参数更新和末批规则连续列举，执行顺序可更自然。','按训练前预算、单次反向传播和无增强/末批情况展开。','算法补充信息可直接对应实现环节，而非孤立配置清单。','每篇文档的参考预算为最多四次尝试、最多接受两个变体，具体训练更新数按公共实验协议确定。每次反向传播中，全局LoRA、触发的连续提示及辅助头沿各自损失路径更新，结论专项分支由生成损失更新。没有增强样本时仍保留原文监督；梯度累积遇到未满的最后一批时，按实际源文档数归一化。')
edit(486,'输运性质：明确条件、证明及适用对象','形式条件、证明和语义限制紧密排列，证明究竟保证什么可更醒目。','保持数学条件不变，以双射和完整端点映射分别解释组件与关系结构保持。','读者更容易理解这是标注结构的保持性质，不能据此推出自然语言语义保持。','性质一：标注输运保持。 若改写槽位互不冲突、ϕ 为组件双射，且类型及每个完整关系因素均按 ϕ 输运，则 G 与 ϕG 保持相同的组件数、组件类型以及带方向和标签的关联结构。证明如下：双射使每个原组件恰好对应一个新组件；完整端点逐一映射，使关系及超边既不新增也不丢失，逆映射即可恢复原图。该性质保证标注对象的结构保持，不能证明改写后的自然语言仍支持这些标签。')
edit(487,'预测性质：明确充分条件与平均指标的距离','单因素条件的推导与平均JS指标的限制可更紧密对应。','保留全部符号与不等式，调整证明引导和结尾说明。','读者可直接区分逐因素充分条件、平均对齐损失和原预测正确性。','性质二：单因素预测稳定的充分条件。 对某一因素，设原视图的正确类别为 y，分布 p 的间隔为 δ=py−maxk≠ypk>0。若增强视图分布 q 满足 ∥p−q∥∞<δ/2，则有 argmaxq=y。其原因是，对任意 k≠y，qy−qk>py−pk−δ≥0。该条件针对单个因素成立；平均 JS 降低既不意味着所有因素均满足此界，也不能使原先错误的预测自动变为正确。')
edit(488,'性质边界：先限定约束对象，再说明评价依据','通用定理、严格等变和效果破坏因素连续出现，限制的层次可以更清楚。','先说明两项性质解释的对象，再列出超出形式保证的实际风险。','理论性质与实证效果之间的关系明确，保留真实测试文本作为最终判断依据。','上述性质分别说明标注输运和单因素预测约束的作用范围，不构成新的通用等变学习定理。本章约束辅助图因素的分布，并未证明自回归生成的完整图分布严格等变。语义漂移、审核器偏差、金标噪声及候选宇宙外关系仍可能影响效果，因此最终评价依据是未参与增强的真实测试文本。')
edit(491,'比较设置：按继承基线、数据策略和对齐目标分组介绍','九个配置逐项串列，读者难以立即判断每组用于回答什么问题。','保留九组定义，按基线与辅助头、增强构造、成对目标和可选策略依次展开。','对照组的实验目的更清晰，相同推理条件、训练预算及成本口径也更易查阅。','T0I0采用包含BR-O推理的完整继承配置，Heads在其上仅增加辅助头。Plain与QOS分别考察普通增强和槽位化增强；NoPair使用可靠因素监督但不进行对齐，CompPair仅对齐组件，T1I0同时对齐组件与关系。FullFilter和RandomCenter分别考察完整影响域筛选与匹配随机中心。九组使用相同骨干、源文档访问次数及有效更新步数，推理均采用I0。增强组按500／900个接受视图匹配规模，成本包括生成失败、拒绝视图及审核。')
edit(492,'消融控制：让共享视图与目标差异直接对应','共用文件、因素总体和控制变量分开陈述，读者需要自行推断其对消融的意义。','先声明共享条件，再解释因素来源，最后明确数量和掩码在比较中固定。','成对目标的独立比较依据更清楚，也保留CDCP未知子集的处理规则。','NoPair、CompPair与T1I0复用同一批视图和关系掩码，文件摘要见附录A。其因素总体由原生标注与声明的有限NONE宇宙确定，CDCP中语义未知的联合源真子集不作为NONE。三组比较因此保持视图数量与监督掩码不变。')
edit(498,'主结果：区分均值提升与校正后的显著性','配置均值和配对增量并列，最后的显著性判断可以更直接落到两个语料。','先给出两组均值，再报告配对增量及校正p值，分别判断是否达标。','读者不会仅根据表中排序认定两种语料均显著提升。','在同一9B骨干下，T0I0的AAEC和CDCP严格关系F1分别为65.69、41.79，T1I0分别为68.25、45.08。训练配置的配对增量为2.56／3.30个百分点，对应的Holm校正p值为0.0550与0.0300。因此，CDCP达到校正后的显著性标准，AAEC未达到；两种语料的均值提升不能一概解释为统计显著。')
edit(501,'独立贡献：将证据限定放在具体比较旁边','独立贡献的实验条件与统计结论虽完整，但末句可更准确地对应当前证据。','保留固定视图、掩码和辅助头条件，分别报告两种语料结果，再限定结论适用范围。','成对目标的证据与整套配置的证据区分更清楚，避免把局部显著结果扩展为跨语料稳定收益。','在视图、掩码与辅助头相同的条件下，T1I0−NoPair直接检验成对目标的贡献。AAEC的差值为1.39个百分点，单项95%区间为[0.28, 2.46]，Holm p=0.1439；CDCP的差值为2.57个百分点，单项95%区间为[1.05, 4.23]，Holm p=0.0495。CDCP的校正p值略低于0.05，AAEC未达到该标准。这支持成对目标在当前CDCP条件下的增益，尚不足以认定它在不同语料上均有稳定的独立收益。')
edit(502,'探索性比较：明确哪些观察不进入主结论','探索性身份、主结论边界和不同模块作用之间衔接略显跳跃。','先说明比较身份和结果位置，再以各部分承担不同作用解释为何不混合归因。','读者可以区分探索性结果与主要证据，不把数据选择、监督和对齐的作用相互替代。','普通增强、QOS式适配、完整筛选与随机中心的比较均属探索性分析，其逐种子差值和区间见表3-6。因素掩码的数据选择、辅助头监督及分布对齐承担不同作用；未获相应比较支持的独立优势不写入主结论。')
edit(504,'审核设计：按角色、培训和抽样顺序组织','审核者角色、培训材料与抽样规则集中列举，审计流程不够顺畅。','将独立判断与裁决放在一起，再介绍培训和分层抽样的执行条件。','读者更易复核谁作判断、怎样统一规范、从哪个总体抽取审核因素。','审核者A、B分别将因素判为stable（状态保持）、changed（状态改变）、undecided（待定）或original_disagreement（原标签分歧）；裁决者C先独立判断，再形成参照。三人使用60项培训材料统一规范，培训一致性κ为0.86。组件审核同时覆盖接受和拒绝项目。关系审核从训练增强池分四层抽样，每层至多300项，不足300项时全数审核。抽样概率为πh=nh/Nh，记录均绑定源文档、视图及因素身份。')
edit(510,'区间解释：先说明相关性，再引出源聚类统计','因素级区间与源聚类区间并列，但补充后者的原因可更直接。','把同源多视图、多因素导致的依赖放在补充统计之前。','读者能理解不同区间为何并存，并知道它们来自同一批记录。','表3-8的Wilson区间用于因素级描述。同一源文档可贡献多个视图和因素，不能将这些记录视为独立样本。因此，附录J表S2-6补充各层实际源组数及2000次源聚类重采样区间；这些统计与表3-9的总体逆概率加权结果使用同一批审核记录。')
edit(511,'分层风险：避免总体比例掩盖跨边界层结果','分层比例、区间假设与有限池边界连续出现，可更突出不能相互替代的理由。','以具体层的比例和上界为起点，再说明总体率与有限池覆盖各自不能推出什么。','读者能看见跨边界正关系的局部风险，且不会把全数审核误作未来批次稳定保证。','AAEC跨边界正关系层的不安全接受比例为2/123，即1.63%，Wilson上界为5.74%；源聚类区间上界见表S2-6。两种区间依赖的假设不同，且总体0.81%的不安全率不能替代该层结果。π=1表示已完整观察这一固定因素池，有限池的比例仍不足以保证跨来源或未来批次的稳定性。')
edit(514,'统计口径：集中解释分母、权重与源组','分母定义、权重、记录保存及有限总体解释较密集，容易混用不安全率和漂移率。','先并列两种率的分母，再依次说明加权重采样、记录身份和有限池解释。','各比例与区间的统计对象更明确，减少用总体源组数替代分层源组数的误读。','不安全率的分母是被接受因素，漂移率的分母是可判定且原标注有效的因素；undecided与original_disagreement均不计为稳定。计算时按1/πh加权，并以源文档为簇重采样2000次。因素总体、抽样标记、视图身份、双人判断、裁决及训练掩码均已保存。每层源组数须由该层实际成员计算，不能以总体257和401组替代。π=1时，比例已完整描述固定池；源聚类区间反映源文档间的变异，不表示该有限池仍有抽样误差。')
edit(515,'域外检查：连接语境漂移与单列审计的理由','域外风险、总体边界和训练策略比较相继出现，域外记录为何单列可更明确。','先说明只读端点仍可能受影响，再交代域外记录的独立统计与监督范围。','读者不会把域外检查混入影响域统计，也不会据此推断默认掩码已扩大。','只读端点也可能受语境变化影响，端点文字未改并不足以确认其状态稳定。附录H因此单列域外检查；这些记录不混入四层影响域总体，也不扩大默认监督掩码。因素掩码可保留已判定部分，完整筛选则可能拒绝更多视图，两者的训练效果见表3-5。')
edit(519,'成本口径：明确时间、显存和训练规模的计量方式','多个资源与参数数值连续出现，单位所对应的统计量可更直白。','先解释GPU小时与单卡峰值，再给出源访问、更新步和可训练参数。','读者能够按统一口径读表，避免将GPU小时等同于墙钟时间或总显存。','表3-10统一按2张A100 80GB计量资源：GPU小时等于2×墙钟小时，显存取单卡最大峰值。源文档访问次数为5N，有效更新步数为5×ceil(N/32)。基础适配的可训练参数为7,884,801，加入辅助头后分别为AAEC的28,871,687和CDCP的28,873,737。基础权重、线性注意力与视觉分支均冻结。')
edit(521,'案例与总体记录：明确两类材料各自验证什么','案例操作和总体审计记录的区别可更直接对应验证用途。','先概括接纳与拒绝两种结果，再说明确定性回放和自然改写记录的模块归属。','案例的可定位性与总体语义审核不会被混作同一种证据。','essay001完整展示一次部分覆盖掩码接纳和一次组件内容检查拒绝，各片段均可定位到原生语料。该案例采用确定性输运回放；总体审计使用A/V模块的自然改写与语义审核记录。两类记录以模块ID区分。')
edit(522,'跨章衔接：将联合源边界落实到后续评分任务','真子集的对象不匹配与语义未知关系可再明确一步，避免读者在第四章将两者合并。','保留具体语料案例与章节位置，直接说明两种判断不能相互推出。','训练审核和完整对象评分之间的概念边界延续得更清楚。','4.6.4节展示CDCP 00662的原生双源reason。两个单源真子集均不能匹配完整超边，但对象不匹配并不赋予它们语义NONE标签。训练审核与第四章完整对象评分均须保持这一界限。')
edit(524,'小结：依次收束方法作用、实验结论和材料','方法总结与统计结论并列，整体配置与独立成对贡献的区分可更清楚。','先逐项对应机制作用，再明确整体增量与固定条件消融的不同证据。','小结能够独立概括本章贡献，也保留统计结论的语料范围。','本章从字符身份迁移、语义审核和可靠因素学习三个环节处理监督保持问题。组件双射用于追踪对应，因素掩码隔离未确认标签，源归一化控制变体数量带来的权重差异。整体训练配置在两种语料上的增量点估计均为正，CDCP达到多重比较校正后的显著性标准；成对目标的独立贡献则由固定视图与掩码的消融比较判断。坐标案例、分层审核及训练记录为逐项复算提供了材料。')
edit(525,'章间过渡：从训练监督保持引出推理关系同步','原文衔接正确，但训练阶段与下一章具体操作的连接可更直接。','先保留监督保持不能保证预测正确的限制，再落到原文不变时的组件修改。','下一章问题由本章的适用边界自然引出。','训练中的监督保持不能直接保证预测图的全部组件与关系均正确。下一章研究原文不变时的推理过程，重点讨论组件修改后如何同步处理受影响的关系。')

edit(427,'锚定公式引导：理顺变量说明并改善换行','视图与监督集合以顿号直接连接，变量之间的关系不够清楚，落版后还出现顿号独占行首。','先说明标签锚定的理由，再用“以……分别表示……”引出两类监督集合，保留后续分组定义。','变量的定义关系更明确，公式引导句阅读连贯，也消除行首标点问题。','较低的JS散度也可能来自两个视图的共同误判，因此仍需标签锚定。对视图 x，以 MC 和 MR 分别表示受监督组件集合与关系因素集合，令 R+M、R0M 分别为其中的正关系与NONE因素，BM={b∈{+,0}:RbM>0}。辅助监督完整定义为')

